  }

  /* Moderation notices */
  /* Ships #606060 straight on the post card */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .moderation_action,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .moderation_action strong {
    color: #8b949e !important;
  }

  /* Footer */
  /* A creator page's footer sits inside its own #wrapper and creator CSS styles it, so .footer is
     not an itch-only hook — hence the layout guard. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .footer .primary,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .footer .secondary,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .footer .copyright { color: #8b949e !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .footer a { color: #a8b0b8 !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .footer a:hover { color: #e6edf3 !important; }

  /* A white background-image gradient; remap its stops to the page base. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .paddle_next {
    background-image: linear-gradient(to right, rgba(20, 24, 29, 0) 0%, #14181d 50%, #14181d 100%) !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .paddle_prev {
    background-image: linear-gradient(to right, #14181d 0%, #14181d 50%, rgba(20, 24, 29, 0) 100%) !important;
  }

  /* A real DIV pair, not a ::-webkit-scrollbar: its rgba(0,0,0,0.1) track is invisible here and its
     50% red thumb composites muddy over dark. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .game_carousel_widget .scrollbar_outer {
    background-color: #21262d !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .game_carousel_widget .scrollbar_outer .scrollbar_inner {
    background-color: rgba(250, 125, 140, 0.5) !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .game_carousel_widget .scrollbar_outer:hover .scrollbar_inner,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .game_carousel_widget .scrollbar_outer .scrollbar_inner.dragging {
    background-color: #fa7d8c !important;
  }

  /* Home index tab strip (narrow viewports) */
  /* The 4px transparent bottom border is a spacer itch reddens on .active/:hover; the blanket reset
     is !important and beats that. Below the breakpoint this strip IS the site nav. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .index_header_tabs > a {
    border-bottom-color: transparent !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .index_header_tabs > a.active,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .index_header_tabs > a:hover {
    border-bottom-color: #fa7d8c !important;
  }

  /* Large promo / hero sections */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .large_promo_section { background-color: #0d1117 !important; }
  /* The backdrop is the game's own blurred cover art, of unpredictable lightness, and our overlay
     sits BEHIND it — hence itch's white caption. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_link a {
    color: #ffffff !important;
  }
  /* A mid-tone band: white label in a translucent-white ring, which the border reset would
     blacken. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .app_banner .outline_button {
    color: #ffffff !important;
    border-color: rgba(255, 255, 255, 0.6) !important;
  }
  /* Hover flips it to a solid brand-red fill with a white label. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .app_banner .outline_button:hover {
    color: #ffffff !important;
  }
  /* A saturated blue band written on in white. Its `.button.outline` child keeps our chip styling —
     that rule outranks these. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_banner,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_banner p,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_banner h4 {
    color: #ffffff !important;
  }
  /* Ships a 30% white overlay */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_game_promo_banner_widget {
    background-color: rgba(13, 17, 23, 0.55) !important;
  }
  /* SOLID black, not a translucent overlay — its gradient fades to transparent at the right, so a
     translucent fill would let the grid show through. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_mobile_banner_widget {
    background-color: #0d1117 !important;
  }
  /* Its gradient is a per-video accent, so itch writes the bar white and Subscribe as an outlined
     glass pill. Below 650px only. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_mobile_banner_widget,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_mobile_banner_widget a,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_mobile_banner_widget .subscribe_button {
    color: #ffffff !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget):not(.widget_layout_widget) .youtube_mobile_banner_widget .subscribe_button {
    background-color: rgba(255, 255, 255, 0.2) !important;
    border: 2px solid rgba(255, 255, 255, 0.85) !important;
  }
}
